-- Hand-written: T11 deed of assignment: born a draft for an accepted proposal or estimate, the status flow, Schedules filled before finalising, frozen once final, set-once PDFs, only an erased client's draft or cancelled deed is deleted, generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `deeds_insert` BEFORE INSERT ON `deeds` WHEN NEW.status IS NOT 'draft' OR NEW.`fy` IS NOT NULL OR NEW.`number` IS NOT NULL OR NEW.`number_display` IS NOT NULL OR NEW.`made_on` IS NOT NULL OR NEW.`sched_deliverables` IS NOT NULL OR NEW.`sched_location` IS NOT NULL OR NEW.`sched_delivered_dates` IS NOT NULL OR NEW.`sched_tools` IS NOT NULL OR NEW.`sched_third_party` IS NOT NULL OR NEW.`snapshot` IS NOT NULL OR NEW.`snapshot_sha256` IS NOT NULL OR NEW.`finalised_at` IS NOT NULL OR NEW.`finalised_by` IS NOT NULL OR NEW.`cancelled_at` IS NOT NULL OR NEW.`cancelled_by` IS NOT NULL OR NEW.`cancel_reason` IS NOT NULL OR NEW.`unsigned_r2_key` IS NOT NULL OR NEW.`unsigned_sha256` IS NOT NULL OR NEW.`signed_r2_key` IS NOT NULL OR NEW.`signed_sha256` IS NOT NULL OR NEW.`signed_size` IS NOT NULL OR NEW.`esign_at` IS NOT NULL OR NEW.`esign_txn` IS NOT NULL OR NEW.`signed_at` IS NOT NULL OR NEW.`signed_by` IS NOT NULL
    OR NOT EXISTS (SELECT 1 FROM projects dp WHERE dp.id = NEW.project_id AND dp.client_id = NEW.client_id AND dp.source_document_id = NEW.source_document_id)
    OR NOT EXISTS (SELECT 1 FROM documents ds WHERE ds.id = NEW.source_document_id AND ds.client_id = NEW.client_id AND ds.type IN ('proposal', 'estimate') AND ds.status = 'accepted' AND ds.frozen_at IS NOT NULL)
    OR EXISTS (SELECT 1 FROM clients dz WHERE dz.id = NEW.client_id AND dz.anonymised_at IS NOT NULL) BEGIN SELECT RAISE(ABORT, 'deeds_insert: a deed starts as a draft for a project of its client, naming the accepted proposal or estimate behind it, while the client is live'); END;
