CREATE TRIGGER `deeds_status_flow` BEFORE UPDATE OF status ON `deeds` WHEN NEW.status IS NOT OLD.status AND NOT ((OLD.status = 'draft' AND NEW.status IN ('final', 'cancelled')) OR (OLD.status = 'final' AND NEW.status = 'signed')) BEGIN SELECT RAISE(ABORT, 'deeds_status_flow: a deed moves from draft to final or cancelled, and from final to signed, never back'); END;
