CREATE TRIGGER `deeds_finalise_ready` BEFORE UPDATE OF status ON `deeds` WHEN OLD.status = 'draft' AND NEW.status = 'final' AND (trim(coalesce(NEW.`sched_deliverables`, '')) = '' OR trim(coalesce(NEW.`sched_location`, '')) = '' OR trim(coalesce(NEW.`sched_delivered_dates`, '')) = '' OR trim(coalesce(NEW.`sched_tools`, '')) = '' OR trim(coalesce(NEW.`sched_third_party`, '')) = '' OR EXISTS (SELECT 1 FROM clients dz WHERE dz.id = OLD.client_id AND dz.anonymised_at IS NOT NULL)) BEGIN SELECT RAISE(ABORT, 'deeds_finalise_ready: a deed is finalised only with both Schedules filled in, while the client is live'); END;
