CREATE TRIGGER `deeds_sign_ready` BEFORE UPDATE OF status ON `deeds` WHEN OLD.status = 'final' AND NEW.status = 'signed' AND EXISTS (SELECT 1 FROM clients dz WHERE dz.id = OLD.client_id AND dz.anonymised_at IS NOT NULL) BEGIN SELECT RAISE(ABORT, 'deeds_sign_ready: a signed copy is added only while the client is live'); END;
