CREATE TRIGGER `deeds_identity_fixed` BEFORE UPDATE ON `deeds` WHEN NEW.`client_id` IS NOT OLD.`client_id` OR NEW.`project_id` IS NOT OLD.`project_id` OR NEW.`source_document_id` IS NOT OLD.`source_document_id` OR NEW.`created_at` IS NOT OLD.`created_at` BEGIN SELECT RAISE(ABORT, 'deeds_identity_fixed: the parties and the accepted version of a deed never change'); END;
