CREATE TRIGGER `deeds_frozen` BEFORE UPDATE ON `deeds` WHEN OLD.status = 'cancelled' OR (OLD.status IN ('final', 'signed') AND (NEW.`fy` IS NOT OLD.`fy` OR NEW.`number` IS NOT OLD.`number` OR NEW.`number_display` IS NOT OLD.`number_display` OR NEW.`made_on` IS NOT OLD.`made_on` OR NEW.`sched_deliverables` IS NOT OLD.`sched_deliverables` OR NEW.`sched_location` IS NOT OLD.`sched_location` OR NEW.`sched_delivered_dates` IS NOT OLD.`sched_delivered_dates` OR NEW.`sched_tools` IS NOT OLD.`sched_tools` OR NEW.`sched_third_party` IS NOT OLD.`sched_third_party` OR NEW.`snapshot` IS NOT OLD.`snapshot` OR NEW.`snapshot_sha256` IS NOT OLD.`snapshot_sha256` OR NEW.`finalised_at` IS NOT OLD.`finalised_at` OR NEW.`finalised_by` IS NOT OLD.`finalised_by` OR NEW.`cancelled_at` IS NOT OLD.`cancelled_at` OR NEW.`cancelled_by` IS NOT OLD.`cancelled_by` OR NEW.`cancel_reason` IS NOT OLD.`cancel_reason`)) BEGIN SELECT RAISE(ABORT, 'deeds_frozen: a final or signed deed keeps its number, Schedules and snapshot, and a cancelled deed never changes'); END;
