CREATE TRIGGER `deeds_set_once` BEFORE UPDATE ON `deeds` WHEN (OLD.`unsigned_r2_key` IS NOT NULL AND NEW.`unsigned_r2_key` IS NOT OLD.`unsigned_r2_key`) OR (OLD.`unsigned_sha256` IS NOT NULL AND NEW.`unsigned_sha256` IS NOT OLD.`unsigned_sha256`) OR (OLD.`signed_r2_key` IS NOT NULL AND NEW.`signed_r2_key` IS NOT OLD.`signed_r2_key`) OR (OLD.`signed_sha256` IS NOT NULL AND NEW.`signed_sha256` IS NOT OLD.`signed_sha256`) OR (OLD.`signed_size` IS NOT NULL AND NEW.`signed_size` IS NOT OLD.`signed_size`) OR (OLD.`esign_at` IS NOT NULL AND NEW.`esign_at` IS NOT OLD.`esign_at`) OR (OLD.`esign_txn` IS NOT NULL AND NEW.`esign_txn` IS NOT OLD.`esign_txn`) OR (OLD.`signed_at` IS NOT NULL AND NEW.`signed_at` IS NOT OLD.`signed_at`) OR (OLD.`signed_by` IS NOT NULL AND NEW.`signed_by` IS NOT OLD.`signed_by`)
