CREATE TRIGGER `deeds_no_delete` BEFORE DELETE ON `deeds` WHEN OLD.status NOT IN ('draft', 'cancelled') OR NOT EXISTS (SELECT 1 FROM clients dz WHERE dz.id = OLD.client_id AND dz.anonymised_at IS NOT NULL) BEGIN SELECT RAISE(ABORT, 'deeds_no_delete: only a draft or cancelled deed of an anonymised client is deleted; a final or signed deed is kept'); END;
